<script setup>
import { computed } from "vue";
import { Head, useForm } from "@inertiajs/vue3";
import AppLayout from "../../Layouts/AppLayout.vue";
import PageBanner from "../../Components/PageBanner.vue";
defineOptions({ layout: AppLayout });
const props = defineProps({ items: Array, history: Array, store_url: String, idempotency_key: String, can_post: Boolean });
const localNow = () => new Date(Date.now() - new Date().getTimezoneOffset() * 60000).toISOString().slice(0, 16);
const form = useForm({ reason: "", vendor_do_number: "", receiver_name: "", received_at: localNow(), idempotency_key: props.idempotency_key, lines: [{ item_id: "", bucket: "", quantity: 1 }] });
const add = () => form.lines.push({ item_id: "", bucket: "", quantity: 1 });
const selected = (line) => props.items.find((item) => item.id === line.item_id);
const submit = () => form.transform((data) => ({ ...data, lines: data.lines.map((line) => { const [vendor_item_id, location_id] = line.bucket.split("|"); return { item_id: line.item_id, vendor_item_id: vendor_item_id || null, location_id, quantity: line.quantity }; }) })).post(props.store_url, { onSuccess: () => { form.idempotency_key = crypto.randomUUID(); form.lines = [{ item_id: "", bucket: "", quantity: 1 }]; } });
const hasItems = computed(() => props.items.length > 0);
</script>
<template><Head title="Manual Data IN"/><div class="units-page"><PageBanner title="Manual Data IN" description="Catat kedatangan urgent tanpa Vendor Refill. Posting ini langsung menambah stok." icon="arrowDown"/><div v-if="Object.keys(form.errors).length" class="field-error" role="alert"><strong>Data IN belum berhasil.</strong><ul><li v-for="(error,key) in form.errors" :key="key">{{ error }}</li></ul></div><section v-if="can_post" class="surface-card form-card"><form class="form-card__body form-stack" @submit.prevent="submit"><div class="form-grid"><label>Nomor DO (opsional)<input v-model="form.vendor_do_number" class="form-input"/></label><label>Waktu diterima<input v-model="form.received_at" type="datetime-local" class="form-input" required/></label></div><label>Nama penerima<input v-model="form.receiver_name" class="form-input" required/></label><label>Alasan urgent<textarea v-model="form.reason" class="form-input" required/></label><fieldset><legend>Barang diterima</legend><div v-for="(line,index) in form.lines" :key="index" class="form-grid"><select v-model="line.item_id" class="form-input" required @change="line.bucket='' "><option value="">Pilih barang</option><option v-for="item in items" :key="item.id" :value="item.id">{{ item.code }} · {{ item.name }} ({{ item.ownership }})</option></select><select v-model="line.bucket" class="form-input" required><option value="">Pilih {{ selected(line)?.ownership === 'CONSIGNMENT' ? 'Vendor · lokasi' : 'lokasi' }}</option><option v-for="bucket in selected(line)?.buckets || []" :key="`${bucket.vendor_item_id}|${bucket.location_id}`" :value="`${bucket.vendor_item_id || ''}|${bucket.location_id}`">{{ bucket.label }}</option></select><input v-model="line.quantity" type="number" min="1" step="1" class="form-input" aria-label="Quantity" required/></div><button type="button" class="button button--secondary" :disabled="!hasItems" @click="add">Tambah barang</button></fieldset><button class="button button--primary" :disabled="form.processing || !hasItems">Posting Data IN</button></form></section><section v-else class="surface-card"><p>Hanya Warehouse yang dapat memposting. Admin dapat melihat riwayat.</p></section><section class="surface-card"><h2>Riwayat terbaru</h2><div class="table-scroll"><table class="data-table"><thead><tr><th>Nomor</th><th>Waktu</th><th>Penerima</th><th>DO</th><th>Baris</th><th>Status</th></tr></thead><tbody><tr v-for="receipt in history" :key="receipt.number"><td>{{ receipt.number }}</td><td>{{ receipt.received_at }}</td><td>{{ receipt.receiver }}<br/><small>{{ receipt.posted_by }}</small></td><td>{{ receipt.do_number || '—' }}</td><td>{{ receipt.line_count }}</td><td>{{ receipt.status }}</td></tr></tbody></table></div><p v-if="!history.length" class="page-note">Belum ada Manual Data IN.</p></section></div></template>
